//! Unicode data for regular expressions: property escapes (§22.2.2.9) and case folding,
//! loaded once from `unicode_props.txt` (generated by scripts/gen-unicode-props.py).

use std::collections::HashMap;
use std::sync::OnceLock;

const DATA: &str = include_str!("unicode_props.txt");

pub type Ranges = Vec<(u32, u32)>;

pub struct Tables {
    pub binary: HashMap<&'static str, Ranges>,
    pub gc: HashMap<&'static str, Ranges>,
    pub script: HashMap<&'static str, Ranges>,
    pub scx: HashMap<&'static str, Ranges>,
    /// `B:`, `G:`, `S:` aliases → canonical names.
    pub alias: HashMap<String, &'static str>,
    pub strings: HashMap<&'static str, Vec<Vec<u32>>>,
    pub fold: HashMap<u32, u32>,
    /// Characters with the same simple case folding (beyond themselves).
    pub fold_class: HashMap<u32, Vec<u32>>,
}

fn parse_ranges(s: &str) -> Ranges {
    s.split(',')
        .filter(|x| !x.is_empty())
        .filter_map(|r| match r.split_once('-') {
            Some((a, b)) => Some((u32::from_str_radix(a, 16).ok()?, u32::from_str_radix(b, 16).ok()?)),
            None => u32::from_str_radix(r, 16).ok().map(|v| (v, v)),
        })
        .collect()
}

pub fn tables() -> &'static Tables {
    static T: OnceLock<Tables> = OnceLock::new();
    T.get_or_init(|| {
        let mut t = Tables {
            binary: HashMap::new(),
            gc: HashMap::new(),
            script: HashMap::new(),
            scx: HashMap::new(),
            alias: HashMap::new(),
            strings: HashMap::new(),
            fold: HashMap::new(),
            fold_class: HashMap::new(),
        };
        for line in DATA.lines() {
            let mut it = line.splitn(3, ' ');
            let (Some(kind), Some(name)) = (it.next(), it.next()) else { continue };
            let rest = it.next().unwrap_or("");
            match kind {
                "B" => {
                    t.binary.insert(name, parse_ranges(rest));
                }
                "G" => {
                    t.gc.insert(name, parse_ranges(rest));
                }
                "S" => {
                    t.script.insert(name, parse_ranges(rest));
                }
                "X" => {
                    t.scx.insert(name, parse_ranges(rest));
                }
                "A" => {
                    t.alias.insert(name.to_string(), rest);
                }
                "E" => {
                    let seqs = rest
                        .split(',')
                        .filter(|x| !x.is_empty())
                        .map(|s| s.split('_').filter_map(|c| u32::from_str_radix(c, 16).ok()).collect())
                        .collect();
                    t.strings.insert(name, seqs);
                }
                "F" => {
                    for pair in name.split(',').chain(rest.split(',')) {
                        if let Some((a, b)) = pair.split_once(':') {
                            if let (Ok(a), Ok(b)) = (u32::from_str_radix(a, 16), u32::from_str_radix(b, 16)) {
                                t.fold.insert(a, b);
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        let mut classes: HashMap<u32, Vec<u32>> = HashMap::new();
        for (&a, &b) in &t.fold {
            classes.entry(b).or_default().push(a);
        }
        for (canon, members) in classes {
            let mut all = members.clone();
            all.push(canon);
            for &m in &all {
                let others: Vec<u32> = all.iter().copied().filter(|&x| x != m).collect();
                t.fold_class.insert(m, others);
            }
        }
        t
    })
}

/// The ranges of `\p{name}` / `\p{name=value}` (None: unknown, the validator rejects it).
pub fn property(name: &str, value: Option<&str>) -> Option<Ranges> {
    let t = tables();
    match value {
        None => {
            if let Some(r) = t.binary.get(name) {
                return Some(r.clone());
            }
            if let Some(c) = t.alias.get(&format!("B:{name}")) {
                return t.binary.get(c).cloned();
            }
            gc(t, name)
        }
        Some(v) => match name {
            "General_Category" | "gc" => gc(t, v),
            "Script" | "sc" => t.script.get(t.alias.get(&format!("S:{v}")).copied().unwrap_or(v)).cloned(),
            "Script_Extensions" | "scx" => {
                t.scx.get(t.alias.get(&format!("S:{v}")).copied().unwrap_or(v)).cloned()
            }
            _ => None,
        },
    }
}

fn gc(t: &Tables, v: &str) -> Option<Ranges> {
    t.gc.get(v).or_else(|| t.alias.get(&format!("G:{v}")).and_then(|c| t.gc.get(c))).cloned()
}

/// A property of strings (`\p{RGI_Emoji}` with the v flag).
pub fn string_property(name: &str) -> Option<Vec<Vec<u32>>> {
    tables().strings.get(name).cloned()
}

/// Simple case folding (scf), Canonicalize for /u and /v (§22.2.2.7.3).
pub fn simple_fold(c: u32) -> u32 {
    tables().fold.get(&c).copied().unwrap_or(c)
}

/// Canonicalize without /u: toUppercase when that gives one code unit, but never mapping
/// non-ASCII to ASCII (§22.2.2.7.3 steps 3–9).
pub fn upper_canon(c: u32) -> u32 {
    let Some(ch) = char::from_u32(c) else { return c };
    let mut up = ch.to_uppercase();
    let (Some(u), None) = (up.next(), up.next()) else { return c };
    let u = u as u32;
    if u > 0xFFFF || (c >= 128 && u < 128) {
        return c;
    }
    u
}
